use openarch_api::Session;
use serde_json::{json,Value};
fn call(s:&mut Session,m:&str,p:Value)->Value{s.handle(m,&p).unwrap_or_else(|e|panic!("{m}: {e}"))}
fn rect(x:f64,y:f64,w:f64,h:f64)->Value{json!([{"type":"line","a":{"x":x,"y":y},"b":{"x":x+w,"y":y}},{"type":"line","a":{"x":x+w,"y":y},"b":{"x":x+w,"y":y+h}},{"type":"line","a":{"x":x+w,"y":y+h},"b":{"x":x,"y":y+h}},{"type":"line","a":{"x":x,"y":y+h},"b":{"x":x,"y":y}}])}
fn setup()->(Session,u64,u64,u64){let mut s=Session::new();let info=call(&mut s,"doc_info",json!({}));let view=info["views"].as_array().unwrap().iter().find(|v|v["view_kind"]=="floor_plan").unwrap()["id"].as_u64().unwrap();let sheet=call(&mut s,"add_sheet",json!({"number":"A101","name":"Plan"}))["id"].as_u64().unwrap();let rev=call(&mut s,"add_revision",json!({}))["id"].as_u64().unwrap();(s,view,sheet,rev)}
#[test]
fn clouds_harvest_views_and_manual_revisions_without_visibility_affecting_membership(){let(mut s,v,sh,r)=setup();call(&mut s,"patch_view",json!({"id":v,"patch":{"crop":{"enabled":true,"region":[{"x":0,"y":0},{"x":10000,"y":10000}]}}}));call(&mut s,"place_view",json!({"sheet":sh,"view":v,"centre":[200,200]}));let cloud=call(&mut s,"add_revision_cloud",json!({"cloud":{"view":v,"revision":r,"curves":rect(1000.0,1000.0,2000.0,1000.0)},"tag":true}))["id"].as_u64().unwrap();assert_eq!(call(&mut s,"sheet",json!({"id":sh}))["applicable_revisions"],json!([r]));call(&mut s,"patch_revision",json!({"id":r,"patch":{"visibility":"none","description":"Planning Issue","date":"02/11/2026"}}));assert_eq!(call(&mut s,"revision_drawing",json!({"view_id":v}))["revision_tags"].as_array().unwrap().len(),0);assert_eq!(call(&mut s,"sheet",json!({"id":sh}))["applicable_revisions"],json!([r]));call(&mut s,"patch_revision_cloud",json!({"id":cloud,"patch":{"curves":rect(20000.0,20000.0,1000.0,1000.0)}}));assert_eq!(call(&mut s,"sheet",json!({"id":sh}))["applicable_revisions"],json!([]));call(&mut s,"set_sheet_revisions",json!({"sheet_id":sh,"ids":[r]}));assert_eq!(call(&mut s,"sheet",json!({"id":sh}))["applicable_revisions"],json!([r]));}
#[test]
fn issued_records_and_clouds_are_protected_including_deleting_the_owner(){let(mut s,v,_,r)=setup();let cloud=call(&mut s,"add_revision_cloud",json!({"cloud":{"view":v,"revision":r,"curves":rect(0.0,0.0,1000.0,1000.0)}}))["id"].as_u64().unwrap();call(&mut s,"patch_revision",json!({"id":r,"patch":{"issued":true}}));assert!(s.handle("patch_revision",&json!({"id":r,"patch":{"description":"Changed"}})).is_err());assert!(s.handle("patch_revision_cloud",&json!({"id":cloud,"patch":{"inverted":true}})).is_err());assert!(s.handle("delete",&json!({"ids":[cloud]})).is_err());assert!(s.handle("delete",&json!({"ids":[v]})).is_err());assert!(s.handle("add_revision_cloud",&json!({"cloud":{"view":v,"revision":r,"curves":rect(0.0,0.0,1000.0,1000.0)}})).is_err());call(&mut s,"patch_revision",json!({"id":r,"patch":{"issued":false}}));call(&mut s,"delete",json!({"ids":[cloud]}));call(&mut s,"undo",json!({}));assert_eq!(call(&mut s,"revision_drawing",json!({"view_id":v}))["revision_clouds"][0]["id"],cloud);}
#[test]
fn per_sheet_numbering_custom_sequences_and_fixed_height_title_block_tables(){let(mut s,_,sh,r)=setup();let mut data=call(&mut s,"revisions",json!({}));data["settings"]["numbering"]=json!("sheet");data["settings"]["sequences"][0]["prefix"]=json!("P");data["settings"]["sequences"][0]["digits"]=json!(2);call(&mut s,"set_revision_settings",json!({"settings":data["settings"]}));let r2=call(&mut s,"add_revision",json!({}))["id"].as_u64().unwrap();call(&mut s,"set_sheet_revisions",json!({"sheet_id":sh,"ids":[r2]}));let family=data["title_blocks"][0]["id"].clone();call(&mut s,"patch_sheet",json!({"id":sh,"patch":{"title_block":family}}));let mut table=data["title_blocks"][0]["table"].clone();table["fixed_rows"]=json!(1);table["rotation"]=json!(90);call(&mut s,"set_revision_table",json!({"family_id":family,"table":table}));let result=call(&mut s,"sheet",json!({"id":sh}));assert_eq!(result["revision_table"]["rows"][0]["cells"][0],"P01");call(&mut s,"set_sheet_revisions",json!({"sheet_id":sh,"ids":[r,r2]}));let result=call(&mut s,"sheet",json!({"id":sh}));assert_eq!(result["revision_table"]["rows"].as_array().unwrap().len(),1);assert_eq!(result["revision_table"]["rows"][0]["cells"][0],"P02");assert_eq!(result["revision_table"]["style"]["rotation"],90);let path=std::env::temp_dir().join(format!("openarch-revisions-{}.oab",std::process::id()));call(&mut s,"save",json!({"path":path}));let mut reopened=Session::new();call(&mut reopened,"open",json!({"path":path}));assert_eq!(call(&mut reopened,"sheet",json!({"id":sh}))["revision_table"],result["revision_table"]);std::fs::remove_file(path).unwrap();}
